import{_ as r,o as t,c as n,a3 as a}from"./chunks/framework.B5WAEDB7.js";const c=JSON.parse('{"title":"Versionsverlauf","description":"Änderungen an einem Eintrag nachvollziehen und frühere Werte wiederherstellen.","frontmatter":{"title":"Versionsverlauf","description":"Änderungen an einem Eintrag nachvollziehen und frühere Werte wiederherstellen."},"headers":[],"relativePath":"grids/versionsverlauf.md","filePath":"grids/versionsverlauf.md","lastUpdated":1786093505000}'),s={name:"grids/versionsverlauf.md"};function i(l,e,d,o,u,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="versionsverlauf" tabindex="-1">Versionsverlauf <a class="header-anchor" href="#versionsverlauf" aria-label="Permalink to &quot;Versionsverlauf&quot;">​</a></h1><p>Der Versionsverlauf zeigt, <strong>wer wann was</strong> an einem Eintrag geändert hat — und erlaubt, frühere Werte zurückzuholen.</p><p>In der Oberfläche heißt der Bereich <strong>Änderungen</strong>.</p><h2 id="verlauf-offnen" tabindex="-1">Verlauf öffnen <a class="header-anchor" href="#verlauf-offnen" aria-label="Permalink to &quot;Verlauf öffnen&quot;">​</a></h2><p>Öffnen Sie einen Eintrag und wechseln Sie zu <strong>Änderungen</strong>.</p><p>Sie sehen je Änderung:</p><table tabindex="0"><thead><tr><th>Angabe</th><th>Beispiel</th></tr></thead><tbody><tr><td>Wer</td><td><em>{Name} hat diesen Eintrag bearbeitet</em></td></tr><tr><td>Wann</td><td>Zeitpunkt</td></tr><tr><td>Was</td><td>Feldname mit <strong>Alt</strong> und <strong>Neu</strong></td></tr></tbody></table><p>Die Anlage erscheint als <em>{Name} hat diesen Eintrag erstellt</em>.</p><p>Ein Klick auf die Zeitangabe wechselt zwischen relativer und absoluter Darstellung: <em>Klicken Sie, um zwischen relativem und absolutem Zeitformat zu wechseln.</em></p><p>Ältere Einträge lädt <strong>Weitere Änderungen laden</strong> nach.</p><h2 id="wer-eine-anderung-ausgelost-hat" tabindex="-1">Wer eine Änderung ausgelöst hat <a class="header-anchor" href="#wer-eine-anderung-ausgelost-hat" aria-label="Permalink to &quot;Wer eine Änderung ausgelöst hat&quot;">​</a></h2><p>Nicht jede Änderung stammt von einem Menschen:</p><table tabindex="0"><thead><tr><th>Anzeige</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Ein Name</td><td>Eine Person hat bearbeitet</td></tr><tr><td><strong>Formular</strong></td><td>Die Änderung kam über ein <a href="/formulare/formular-erstellen">Formular</a></td></tr><tr><td><strong>System oder Flow</strong></td><td>Ein <a href="/flows/was-ist-ein-flow">Flow</a> oder ein automatischer Vorgang</td></tr><tr><td><strong>Unbekannter Benutzer</strong></td><td>Die Person ist nicht mehr auflösbar</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Der schnellste Weg zur Ursache</p><p>Wenn ein Wert „von selbst&quot; gesprungen ist, klärt der Verlauf die Frage meist sofort: Steht dort <em>System oder Flow</em>, prüfen Sie die Flows dieses Grids — vermutlich reagiert einer auf eine Änderung und schreibt zurück.</p></div><p>Leere Werte erscheinen als <strong>(leer)</strong>, Häkchen als <strong>Ja</strong> und <strong>Nein</strong>. Wurde ein Feld inzwischen gelöscht, steht dort <em>Unbekanntes Feld</em>.</p><h2 id="wert-zurucksetzen" tabindex="-1">Wert zurücksetzen <a class="header-anchor" href="#wert-zurucksetzen" aria-label="Permalink to &quot;Wert zurücksetzen&quot;">​</a></h2><p>Über <strong>Auf diesen Wert zurücksetzen</strong> holen Sie einen früheren Wert zurück.</p><div class="warning custom-block"><p class="custom-block-title">Das Zurücksetzen legt eine neue Änderung an</p><blockquote><p><em>Dies löscht den Eintrag im Verlauf nicht. Es erstellt eine neue Änderung mit dem alten Wert.</em></p></blockquote><p>Der Verlauf wird also <strong>nicht</strong> zurückgespult. Es kommt ein weiterer Schritt hinzu, der den alten Wert erneut setzt.</p><p>Das ist gut so — die Historie bleibt vollständig. Aber: Diese neue Änderung ist eine Änderung wie jede andere und kann einen <a href="/flows/trigger">Flow</a> mit dem Auslöser <em>Eintrag wurde geändert</em> starten.</p></div><p>Der Bestätigungsdialog heißt <strong>Neue Änderung mit altem Wert erstellen</strong>.</p><h2 id="aufbewahrungsdauer" tabindex="-1">Aufbewahrungsdauer <a class="header-anchor" href="#aufbewahrungsdauer" aria-label="Permalink to &quot;Aufbewahrungsdauer&quot;">​</a></h2><p>Wie weit der Verlauf zurückreicht, hängt vom Tarif ab. Die Anwendung zeigt es an, etwa:</p><blockquote><p><em>Sie haben 1 Woche Revisionsverlauf.</em></p></blockquote><p>Je nach Tarif erscheinen dort <strong>1 Tag</strong>, <strong>1 Woche</strong> oder <strong>4 Wochen</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Ältere Änderungen sind endgültig weg</p><p>Nach Ablauf der Aufbewahrungsfrist lassen sich frühere Werte nicht mehr einsehen oder zurückholen.</p><p>Für langfristige Nachvollziehbarkeit — etwa aus rechtlichen Gründen — reicht der Versionsverlauf nicht. Legen Sie in dem Fall Änderungen bewusst als Daten ab: ein zusätzliches Grid „Protokoll&quot;, in das ein <a href="/flows/aktionen">Flow</a> bei jeder relevanten Änderung schreibt.</p></div><p>Ist nichts vorhanden, erscheint <em>Kein Revisionsverlauf verfügbar</em>; während des Ladens <em>Revisionsverlauf wird geladen…</em>.</p><h2 id="was-der-verlauf-nicht-abdeckt" tabindex="-1">Was der Verlauf nicht abdeckt <a class="header-anchor" href="#was-der-verlauf-nicht-abdeckt" aria-label="Permalink to &quot;Was der Verlauf nicht abdeckt&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Gelöschte Einträge sind nicht wiederherstellbar</p><p>Der Versionsverlauf protokolliert Änderungen an <strong>Feldwerten</strong> eines bestehenden Eintrags. Ein gelöschter Eintrag ist weg — der Verlauf holt ihn nicht zurück.</p><p>Vor größeren Löschaktionen deshalb einen <a href="/grids/csv-export">CSV-Export</a> ziehen. → <a href="/grids/eintraege-loeschen">Einträge löschen</a></p></div><p>Ebenfalls nicht erfasst: Änderungen an der Struktur — angelegte, umbenannte oder gelöschte Felder, geänderte Ansichten, Formulare und Flows.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/grids/eintraege">Einträge anlegen und bearbeiten</a></li><li><a href="/grids/eintraege-loeschen">Einträge löschen</a></li><li><a href="/grids/csv-export">CSV-Export</a> — Daten sichern</li></ul>',30)])])}const f=r(s,[["render",i]]);export{c as __pageData,f as default};
